import{_ as n,o as i,c as t,a2 as e}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Prinsip Dasar Mundurnya Waktu","description":"","frontmatter":{},"headers":[],"relativePath":"id/82-时间回溯基本原则.md","filePath":"id/82-时间回溯基本原则.md"}'),u={name:"id/82-时间回溯基本原则.md"};function r(d,a,s,k,m,l){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="prinsip-dasar-mundurnya-waktu" tabindex="-1">Prinsip Dasar Mundurnya Waktu <a class="header-anchor" href="#prinsip-dasar-mundurnya-waktu" aria-label="Permalink to &quot;Prinsip Dasar Mundurnya Waktu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>82</td></tr><tr><td>Modul</td><td>Interaksi Antar Bidang dan Aturan Waktu</td></tr><tr><td>Kata Kunci Inti</td><td>Mundurnya waktu, pengamatan terlebih dahulu kemudian intervensi terbatas, stabilitas garis waktu, konservasi kausal, penjangkaran neo</td></tr></tbody></table><h2 id="_1-definisi-dan-hakikat-mundurnya-waktu" tabindex="-1">1. Definisi dan Hakikat Mundurnya Waktu <a class="header-anchor" href="#_1-definisi-dan-hakikat-mundurnya-waktu" aria-label="Permalink to &quot;1. Definisi dan Hakikat Mundurnya Waktu&quot;">​</a></h2><p>Mundurnya waktu merujuk pada tindakan mengirimkan kesadaran, informasi, atau materi kembali ke simpul waktu masa lalu melalui kemampuan operasi dimensi waktu dari jaringan hukum neo. Dalam kerangka hukum Hengyuanzhou, waktu bukanlah aliran linier searah yang tidak dapat diubah, melainkan dimensi yang dapat dioperasikan dalam jaringan hukum. Namun, operasi dimensi waktu memiliki risiko yang sangat tinggi dan batasan yang ketat; setiap tindakan mundurnya waktu dapat menyebabkan gangguan rantai kausal, pembelahan garis waktu, bahkan getaran hukum tingkat kosmik.</p><p>Hakikat mundurnya waktu adalah &quot;membuat saluran mundur pada dimensi waktu jaringan hukum, memungkinkan informasi atau energi tertentu menyebar secara terbalik sepanjang saluran&quot;. Proses ini memerlukan konsumsi energi neo yang sangat besar, dan semakin jauh waktu yang dimundurkan, semakin kompleks konten yang dimundurkan, konsumsi energi tumbuh secara eksponensial. Saat ini, kemampuan teknologi Hengyuanzhou hanya mendukung mundurnya waktu pada tingkat kesadaran dan informasi; mundurnya waktu lengkap pada tingkat materi masih dalam tahap penelitian teoretis.</p><p>Perlu ditekankan secara khusus bahwa mundurnya waktu tidak sama dengan &quot;perjalanan waktu&quot;. Orang yang mundur tidak masuk ke masa lalu dalam bentuk materi lengkap, melainkan tiba di simpul waktu target dalam bentuk proyeksi kesadaran atau paket informasi. Keberadaan orang yang mundur selama periode masa lalu adalah &quot;semi-transparan&quot; — dapat mengamati, tetapi kemampuan interaksi fisik dibatasi secara ketat. Desain ini sendiri merupakan bagian dari mekanisme keamanan mundurnya waktu.</p><h2 id="_2-tujuh-prinsip-dasar-mundurnya-waktu" tabindex="-1">2. Tujuh Prinsip Dasar Mundurnya Waktu <a class="header-anchor" href="#_2-tujuh-prinsip-dasar-mundurnya-waktu" aria-label="Permalink to &quot;2. Tujuh Prinsip Dasar Mundurnya Waktu&quot;">​</a></h2><p>Operasi mundurnya waktu Hengyuanzhou mengikuti tujuh prinsip dasar berikut, yang ditetapkan oleh Dewan Neo dalam bentuk resolusi khusus, memiliki kekuatan hukum yang hanya berada di bawah konstitusi:</p><table tabindex="0"><thead><tr><th>Nomor Prinsip</th><th>Nama Prinsip</th><th>Konten Inti</th></tr></thead><tbody><tr><td>Prinsip Pertama</td><td>Pengamatan terlebih dahulu, kemudian intervensi terbatas</td><td>Setiap mundur harus terlebih dahulu menyelesaikan tahap pengamatan murni, dan hanya setelah mengonfirmasi tidak ada risiko signifikan dapat dilakukan intervensi terbatas</td></tr><tr><td>Prinsip Kedua</td><td>Konservasi kausal</td><td>Tindakan mundur tidak dapat mengubah rantai kausal inti yang telah terjadi; penyimpangan kausal yang dihasilkan oleh mundur harus dikoreksi setelah mundur selesai</td></tr><tr><td>Prinsip Ketiga</td><td>Penjangkaran neo</td><td>Semua operasi mundur harus menggunakan neo stabil sebagai asal koordinat waktu; mundur buta tanpa neo dilarang</td></tr><tr><td>Prinsip Keempat</td><td>Dampak minimum</td><td>Semua tindakan selama proses mundur harus mengikuti prinsip dampak minimum, mengurangi gangguan pada garis waktu masa lalu sebanyak mungkin</td></tr><tr><td>Prinsip Kelima</td><td>Dapat dilacak</td><td>Setiap mundur harus mencatat log operasi secara lengkap, termasuk identitas orang yang mundur, waktu target, konten pengamatan, tindakan intervensi, dan evaluasi penyimpangan kausal</td></tr><tr><td>Prinsip Keenam</td><td>Larangan paradoks</td><td>Segala operasi yang dapat menyebabkan paradoks waktu dilarang keras, termasuk namun tidak terbatas pada paradoks kakek, paradoks informasi, dan paradoks ontologis</td></tr><tr><td>Prinsip Ketujuh</td><td>Audit pasca</td><td>Setelah mundur selesai, harus dilakukan audit pasca oleh komite audit hukum waktu independen, untuk mengonfirmasi bahwa tidak ada gangguan garis waktu yang tidak terkendali</td></tr></tbody></table><p>Dari tujuh prinsip, &quot;pengamatan terlebih dahulu, kemudian intervensi terbatas&quot; adalah prinsip operasional yang paling inti, dan enam prinsip lainnya berpusat pada inti ini. Norma operasi rinci dari prinsip ini dapat dilihat pada Dokumen 83 &quot;Pedoman Pengamatan Terlebih Dahulu, Kemudian Intervensi Terbatas&quot;.</p><h2 id="_3-manajemen-klasifikasi-mundurnya-waktu" tabindex="-1">3. Manajemen Klasifikasi Mundurnya Waktu <a class="header-anchor" href="#_3-manajemen-klasifikasi-mundurnya-waktu" aria-label="Permalink to &quot;3. Manajemen Klasifikasi Mundurnya Waktu&quot;">​</a></h2><p>Berdasarkan rentang waktu dan tingkat intervensi mundur, operasi mundurnya waktu dibagi menjadi tiga tingkat manajemen:</p><ol><li><p><strong>Mundur Tingkat 1 (Pengamatan Waktu Dekat)</strong>: Rentang waktu mundur tidak melebihi 100 tahun waktu standar bidang sendiri, dan hanya dilakukan pengamatan murni tanpa intervensi apa pun. Disetujui oleh Biro Administrasi Bidang; proses operasi harus diawasi oleh dua atau lebih pengawas hukum waktu yang hadir.</p></li><li><p><strong>Mundur Tingkat 2 (Pengamatan Waktu Jauh)</strong>: Rentang waktu mundur melebihi 100 tahun tetapi tidak melebihi 10.000 tahun, atau proses mundur memerlukan intervensi yang sangat ringan (seperti mengirimkan satu informasi). Harus disetujui oleh Komite Hukum Waktu di bawah Dewan Neo, dan rencana darurat penyimpangan kausal yang rinci harus disusun.</p></li><li><p><strong>Mundur Tingkat 3 (Intervensi Mendalam)</strong>: Rentang waktu mundur melebihi 10.000 tahun, atau proses mundur memerlukan intervensi substansial. Harus disetujui oleh mayoritas lebih dari dua pertiga dalam rapat pleno Dewan Neo, dan ditinjau oleh Pengadilan Simbiosis untuk memastikan tidak bertentangan dengan konstitusi, guna mengonfirmasi bahwa tindakan intervensi sesuai dengan prinsip dasar Konstitusi Simbiosis.</p></li></ol><p>Mundurnya waktu tingkat apa pun dilarang untuk tujuan berikut: mencari keuntungan pribadi untuk individu atau kelompok kecil, mengubah takdir tokoh sejarah untuk memenuhi keinginan pribadi, memalsukan proses alami evolusi peradaban, dan segala bentuk operasi &quot;revisionisme sejarah&quot;.</p><h2 id="_4-batasan-energi-dan-teknologi-mundurnya-waktu" tabindex="-1">4. Batasan Energi dan Teknologi Mundurnya Waktu <a class="header-anchor" href="#_4-batasan-energi-dan-teknologi-mundurnya-waktu" aria-label="Permalink to &quot;4. Batasan Energi dan Teknologi Mundurnya Waktu&quot;">​</a></h2><p>Konsumsi energi mundurnya waktu sangat besar. Mengambil mundur proyeksi kesadaran sebagai contoh, energi yang diperlukan untuk mundur 1 tahun adalah sekitar 10.000 unit energi standar, untuk mundur 100 tahun adalah sekitar 1 juta unit energi standar, dan untuk mundur 10.000 tahun diperlukan sekitar 10 miliar unit energi standar. Konsumsi energi dan rentang waktu mundur memiliki hubungan yang kira-kira logaritmik-linier, tetapi ketika melewati simpul sejarah yang signifikan akan出现 puncak energi — ini karena kepadatan rantai kausal di simpul sejarah yang signifikan sangat tinggi, dan operasi mundur perlu mengatasi inersia kausal yang lebih besar.</p><p>Pada tingkat teknologi, mundurnya waktu memerlukan kerja sama antara &quot;perangkat penjangkaran hukum waktu&quot; dan &quot;larik transmisi proyeksi kesadaran&quot;. Yang pertama bertanggung jawab untuk menetapkan koordinat waktu yang stabil di simpul waktu target, yang kedua bertanggung jawab untuk mengirimkan proyeksi kesadaran orang yang mundur dengan aman dan mempertahankan keberadaannya selama periode masa lalu. Semua perangkat mundur harus melalui sertifikasi keamanan dari Komite Pengawasan Neo; dilarang menggunakan perangkat buatan sendiri yang tidak bersertifikat untuk operasi mundur.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Mundurnya waktu adalah salah satu kemampuan operasi hukum yang paling kuat dan paling berbahaya di Hengyuanzhou. Tujuh prinsip dasar dan sistem manajemen klasifikasi secara bersama-sama membentuk kerangka keamanan mundurnya waktu, yang semangat intinya adalah &quot;hormat pada kausal, operasi dengan hati-hati&quot;. Penggunaan sah mundurnya waktu hanya terbatas pada penelitian arkeologi, pemulihan kebenaran sejarah, dan peringatan dini krisis tingkat kepunahan; penggunaan apa pun di luar cakupan ini akan dianggap sebagai penodaan terhadap hukum alam semesta.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>83-Pedoman Pengamatan Terlebih Dahulu, Kemudian Intervensi Terbatas</li><li>89-Mekanisme Pencegahan dan Pengendalian Paradoks Waktu</li><li>84-Garis Besar Protokol Arkeologi</li></ul>',21)])])}const g=n(u,[["render",r]]);export{p as __pageData,g as default};
